style.css:
@-moz-document domain("classroom.google.com") {
/* Base background */
    body, .main-content, .UQuaGc, .YVvGBb {
        background: linear-gradient(135deg, #000814, #001d3d, #003566);
        color: #e0f7fa !important;
        font-family: 'Poppins', 'Montserrat', sans-serif !important;
    }

    /* Top bar */
    .jJIgW, .gb_Of, .gb_Fd {
        background: rgba(0, 0, 0, 0.8) !important;
        border-bottom: 1px solid #0066cc !important;
    }

    /* Class cards */
    .UQuaGc {
        background: rgba(0, 25, 51, 0.7) !important;
        border-radius: 12px !important;
        box-shadow: 0 0 15px rgba(0, 153, 255, 0.2);
        transition: all 0.3s ease;
    }

    .UQuaGc:hover {
        background: rgba(0, 40, 80, 0.8) !important;
        box-shadow: 0 0 25px rgba(0, 153, 255, 0.4);
    }

    /* Buttons */
    .VfPpkd-LgbsSe {
        background: linear-gradient(90deg, #00509e, #00b4d8) !important;
        color: white !important;
        border-radius: 20px !important;
        text-transform: uppercase;
        letter-spacing: 1px;
        transition: all 0.2s ease;
    }

    .VfPpkd-LgbsSe:hover {
        background: linear-gradient(90deg, #0077b6, #48cae4) !important;
        box-shadow: 0 0 10px #48cae4;
    }

    /* Links and text */
    a, .QRiHXd, .hgjBDc {
        color: #90e0ef !important;
    }

    a:hover {
        color: #caf0f8 !important;
        text-shadow: 0 0 5px #48cae4;
    }

    /* Stream and assignments */
    .z3vRcc, .z3vRcc .VfPpkd-fmcmS-wGMbrd, .z3vRcc .Q8TCCf {
        background: rgba(0, 20, 40, 0.6) !important;
        border-radius: 10px !important;
        color: #d9f9ff !important;
    }

    /* Scrollbar */
    ::-webkit-scrollbar {
        width: 10px;
    }
    ::-webkit-scrollbar-track {
        background: #000814;
    }
    ::-webkit-scrollbar-thumb {
        background: #0077b6;
        border-radius: 5px;
    }
    ::-webkit-scrollbar-thumb:hover {
        background: #48cae4;
    }

    /* Subtle Billie glow accent */
    * {
        text-shadow: 0 0 2px rgba(0, 200, 255, 0.2);
    }
}
